<?php
namespace SenderSuite;

/** Text renderer shared by the variable registry and future sending workflows. Never sends messages. */
final class Templating {
    public const FIELDS=array('first_name','last_name','business_name','phone_number','email','city','state','country','website','industry');
    private const SPACE='[\x09-\x0D\x1C-\x20\x{0085}\x{00A0}\x{1680}\x{2000}-\x{200A}\x{2028}\x{2029}\x{202F}\x{205F}\x{3000}]';
    public static function pattern($single=false){$s=self::SPACE;return $single?'/\{'.$s.'*([A-Za-z0-9][A-Za-z0-9 ._\-]*?)'.$s.'*(?:\|([^}]*))?\}/u':'/\{\{'.$s.'*([A-Za-z0-9][A-Za-z0-9 ._\-]*?)'.$s.'*(?:\|([^}]*))?\}\}/u';}
    public static function builtin(){return array_merge(self::FIELDS,array('full_name','name','contact','brand_name','brand'));}
    public static function text($value){if($value===null){return '';}if(is_bool($value)){return $value?'True':'False';}if(is_float($value)){return self::floatText($value);}return (string)$value;}
    private static function floatText($value){
        $old=ini_get('serialize_precision');ini_set('serialize_precision','-1');try{$raw=json_encode($value,JSON_PRESERVE_ZERO_FRACTION|JSON_THROW_ON_ERROR);}finally{ini_set('serialize_precision',$old);}
        $sign=strpos($raw,'-')===0?'-':'';$raw=ltrim($raw,'-');$parts=explode('e',strtolower($raw));$mantissa=$parts[0];$exp=isset($parts[1])?(int)$parts[1]:0;$dot=strpos($mantissa,'.');$dot=$dot===false?strlen($mantissa):$dot;$digits=str_replace('.','',$mantissa);$trim=ltrim($digits,'0');if($trim===''){return $sign.'0.0';}$leading=strlen($digits)-strlen($trim);$exponent=$exp+$dot-$leading-1;$digits=rtrim($trim,'0');if($exponent<-4||$exponent>=16){$coefficient=$digits[0].(strlen($digits)>1?'.'.substr($digits,1):'');return $sign.$coefficient.'e'.($exponent<0?'-':'+').str_pad((string)abs($exponent),2,'0',STR_PAD_LEFT);}if($exponent<0){return $sign.'0.'.str_repeat('0',-$exponent-1).$digits;}$position=$exponent+1;if(strlen($digits)<=$position){return $sign.$digits.str_repeat('0',$position-strlen($digits)).'.0';}return $sign.substr($digits,0,$position).'.'.substr($digits,$position);
    }
    public static function key($name){if($name===null||$name===false||$name===0||$name===0.0){return '';}$s=Compat::lower(Compat::strip(self::text($name)));return trim(preg_replace('/[^A-Za-z0-9]+/','_',$s),'_');}
    public static function clean($value){return Compat::strip(self::text($value));}
    public static function custom($contact,$reserved=false){$row=(array)$contact;$raw=$row['custom_fields']??null;if(is_string($raw)){try{$raw=json_decode($raw,false,512,JSON_THROW_ON_ERROR|JSON_BIGINT_AS_STRING);}catch(\Throwable $e){return array();}}if(!is_object($raw)){return array();}$out=array();foreach($raw as $key=>$value){if(is_object($value)||is_array($value)){continue;}$norm=self::key((string)$key);if($reserved&&($norm===''||in_array($norm,array('custom_fields','notes','id'),true))){continue;}$out[$norm]=self::clean($value);}return $out;}
    public static function context($contact){if($contact===null){return array();}$row=(array)$contact;$out=self::custom($contact);foreach(self::FIELDS as $field){$v=self::clean($row[$field]??null);if($v!==''||!array_key_exists($field,$out)){$out[$field]=$v;}}$names=array();foreach(array('first_name','last_name') as $key){if(($out[$key]??'')!==''){$names[]=$out[$key];}}$out['full_name']=implode(' ',$names);$out['name']=$out['full_name']!==''?$out['full_name']:($out['business_name']??'');$out['brand_name']=$out['business_name']??'';$out['brand']=$out['business_name']??'';$out['contact']=$out['name'];return $out;}
    public static function unknown($text,array $known=array()){$pool=array_fill_keys(array_merge(self::builtin(),$known),true);$out=array();$seen=array();preg_match_all(self::pattern(),$text??'',$matches,PREG_SET_ORDER);foreach($matches as $m){$key=self::key($m[1]);if($key!==''&&!isset($pool[$key])&&!isset($seen[$key])){$out[]=Compat::strip($m[1]);$seen[$key]=true;}}return $out;}
    public static function placeholders($body){$out=array();preg_match_all(self::pattern(),$body??'',$matches,PREG_SET_ORDER);foreach($matches as $m){$key=self::key($m[1]);if($key!==''&&!in_array($key,$out,true)){$out[]=$key;}}return $out;}
    private static function resolve($field,$explicit,array $context,array $aliases,array $fallbacks){$key=$aliases[$field]??$field;$value=$context[$key]??'';if($value!==''){return $value;}if($explicit!==null){return Compat::strip($explicit);}$configured=$fallbacks[$key]??'';if($configured===''){$configured=$fallbacks[$field]??'';}if($configured!==''){return $configured;}if(in_array($key,array('first_name','name','full_name','contact'),true)){return ($context['business_name']??'')!==''?$context['business_name']:'there';}return '';}
    public static function tidy($text){$s=self::SPACE;$rules=array('/[ \t]+([,.!?;:])/u'=>'$1','/([,;:])'.$s.'*(?=[,.;:!?])/u'=>'','/\('.$s.'*\)|\['.$s.'*\]|"'.$s.'*"|\''.$s.'*\'/u'=>'','/[ \t]{2,}/u'=>' ','/[ \t]*\n[ \t]*/u'=>"\n",'/\n{3,}/u'=>"\n\n",'/^[ \t]*[,;:]'.$s.'*/um'=>'');foreach($rules as $p=>$replacement){$text=preg_replace($p,$replacement,$text);}return Compat::strip($text);}
    public static function render($body,$contact=null,array $aliases=array(),array $fallbacks=array(),$unknown='drop',array $known=array(),array $overrides=array()){
        if($body===null||$body===''){return '';}$context=self::context($contact);foreach($overrides as $key=>$value){if($value!==null){$context[self::key((string)$key)]=self::clean($value);}}$pool=array_fill_keys(array_merge(array_keys($context),self::builtin(),$known,array_keys($aliases),array_values($aliases)),true);
        $rendered=preg_replace_callback(self::pattern(),function($m)use($context,$aliases,$fallbacks,$unknown,$pool){$field=self::key($m[1]);if($unknown==='mark'&&$field!==''&&!isset($pool[$field])){return '[UNKNOWN VARIABLE: '.Compat::strip($m[1]).']';}return self::resolve($field,$m[2]??null,$context,$aliases,$fallbacks);},$body);
        $rendered=preg_replace_callback(self::pattern(true),function($m)use($context,$aliases,$fallbacks){$field=self::key($m[1]);if(!array_key_exists($field,$context)&&!array_key_exists($field,$aliases)&&!in_array($field,array('first_name','name','full_name','contact'),true)){return $m[0];}return self::resolve($field,$m[2]??null,$context,$aliases,$fallbacks);},$rendered);return self::tidy($rendered);
    }
    public static function segments($message){$gsm="@£\$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞ\x1bÆæßÉ !\"#¤%&'()*+,-./0123456789:;<=>?¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà";$allowed=array_fill_keys(Compat::points($gsm),true);$points=Compat::points($message);$isGsm=true;foreach($points as $p){if(!isset($allowed[$p])){$isGsm=false;break;}}$n=count($points);return array($n,$isGsm?($n<=160?1:intdiv($n+152,153)):($n<=70?1:intdiv($n+66,67)));}
}
